<?php $kat=mysqli_query($koneksi,"SELECT * FROM kategori ORDER BY namakategori"); ?><h2>Tambah Sarana</h2><form action="proses/prosesalat.php?aksi=tambah" method="post" enctype="multipart/form-data"><div class="form-group"><label>Nama Alat</label><input class="form-control" name="namaalat" required></div><div class="form-group"><label>Foto Sarana</label><input class="form-control-file" type="file" name="foto" accept="image/jpeg,image/png,image/webp" required><small class="text-muted">JPG, PNG, WEBP, maksimal 3 MB.</small></div><div class="form-group"><label>Kategori</label><select class="form-control" name="idkategori" required><?php while($k=mysqli_fetch_assoc($kat)): ?><option value="<?=$k['idkategori']?>"><?=htmlspecialchars($k['namakategori'])?></option><?php endwhile;?></select></div><div class="form-row"><div class="form-group col"><label>Jumlah</label><input class="form-control" type="number" name="jumlah" min="0" required></div><div class="form-group col"><label>Kondisi</label><input class="form-control" name="kondisi" value="Baik" required></div><div class="form-group col"><label>Lokasi</label><input class="form-control" name="lokasi" required></div></div><button class="btn btn-primary">Simpan</button></form>